/// <summary>
/// Extension class of form data source SalesTable in form SalesTableListPage
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTableListPage, SalesTable))]
internal final class METSalesTableListPageSalesTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// active method on ST datasource
    /// </summary>
    /// <returns>
    /// int
    /// </returns>
    int active()
    {
        int ret = next active();

        SalesTable salesTable = this.cursor() as SalesTable;
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderCancellation))).enabled(salesTable.SalesStatus == SalesStatus::Canceled);

        return ret;
    }
